/**
 * EpochAssertion tests — the canonical slashable artifact.
 *
 * Byte-compat vectors are generated by yakcoin-consensus
 * (tests/eassert_vector.rs): the JS encoder MUST produce
 * byte-identical preimages or evidence verification forks.
 *
 * @module mesh/tests/epoch-assertion.test
 */

import { describe, test, expect } from 'vitest';
import {
  assertionBytes, selfClaimRef, signAssertion, verifyAssertion,
  selfAssertClaim, EASSERT_DOMAIN,
} from '../epoch-assertion.js';
import { AttestationGossip, claimLeafHash } from '../attestation-gossip.js';
import {
  generateKeyPair, generateNodeId, signMessage, setCodebaseHash,
} from '../../identity/node-key.js';
import { hexToBytes } from '@noble/hashes/utils.js';

// Rust-derived vectors (yakcoin-consensus tests/eassert_vector.rs)
const RUST_BYTES =
  '59414b4d4553482d454153534552542d5631' + 'ab'.repeat(32)
  + '07000000' + '11'.repeat(32) + '22'.repeat(32);
const RUST_CLAIMREF =
  'fa8df7b25b22e9aad6db927e9e18bc22c6e20d117a0a14d909c4f84cd91b0541';

const NODE = 'ab'.repeat(32);

describe('EpochAssertion canonical encoding', () => {
  test('canonical bytes are byte-identical to Rust', () => {
    const b = assertionBytes({
      nodeId: NODE, epoch: 7,
      claimRef: '11'.repeat(32), value: '22'.repeat(32),
    });
    expect(b).not.toBeNull();
    expect(b.length).toBe(118);
    expect(b.toString('hex')).toBe(RUST_BYTES);
  });

  test('selfClaimRef is byte-identical to Rust self_claim_ref', () => {
    expect(selfClaimRef(NODE, 7)).toBe(RUST_CLAIMREF);
  });

  test('rejects malformed fields', () => {
    expect(assertionBytes({ nodeId: 'zz', epoch: 1, claimRef: '11'.repeat(32), value: '22'.repeat(32) })).toBeNull();
    expect(assertionBytes({ nodeId: NODE, epoch: 'x', claimRef: '11'.repeat(32), value: '22'.repeat(32) })).toBeNull();
    expect(assertionBytes({ nodeId: NODE, epoch: 1, claimRef: 'short', value: '22'.repeat(32) })).toBeNull();
  });
});

describe('EpochAssertion sign/verify', () => {
  setCodebaseHash('a'.repeat(64));
  const kp = generateKeyPair(new Uint8Array(32).fill(9));
  const sign = async (b) => signMessage(b, kp.secretKey);

  test('round-trip verifies', async () => {
    const a = await signAssertion({
      nodeId: NODE, epoch: 7,
      claimRef: '11'.repeat(32), value: '22'.repeat(32),
    }, sign, kp.publicKey);
    expect(a.sig).toBeTruthy();
    expect(a.pubkey).toBe(kp.publicKey);
    expect(verifyAssertion(a, kp.publicKey)).toBe(true);
  });

  test('wrong pubkey fails verification', async () => {
    const other = generateKeyPair(new Uint8Array(32).fill(10));
    const a = await signAssertion({
      nodeId: NODE, epoch: 7,
      claimRef: '11'.repeat(32), value: '22'.repeat(32),
    }, sign, kp.publicKey);
    expect(verifyAssertion(a, other.publicKey)).toBe(false);
  });

  test('signer failure produces no assertion — never fabricated', async () => {
    const a = await signAssertion({
      nodeId: NODE, epoch: 7,
      claimRef: '11'.repeat(32), value: '22'.repeat(32),
    }, async () => null);
    expect(a).toBeNull();
  });
});

// ─── attestation-gossip canon integration ────────────────────────────

describe('AttestationGossip canon assertions', () => {
  setCodebaseHash('a'.repeat(64));
  const NOW = () => Math.floor(Date.now() / 30000);

  const canonKp = generateKeyPair(new Uint8Array(32).fill(7));
  const CANON_NODE = 'cc'.repeat(32);
  const canonSign = async (b) => signMessage(b, canonKp.secretKey);

  const mkAttester = (fill) => {
    const kp = generateKeyPair(new Uint8Array(32).fill(fill));
    return { kp, nodeId: generateNodeId(hexToBytes(kp.publicKey)) };
  };
  const A = mkAttester(1);

  const claim = (over = {}) => ({
    version: 1, epoch: 5, yakmeshNodeId: 'peer1', nodeId: NODE,
    seal: [0, 1, 2, 3], spongeRounds: 0, shareCount: 0,
    jobRoot: '0'.repeat(64), entropyFlags: 0, siliconDrift: 0,
    verified: 'verified', ...over,
  });

  const gossip = (claims, opts = {}) => new AttestationGossip({
    nodeId: 'us', publicKey: 'pk', sign: () => 'sig',
    claimLedger: { epochClaims: () => claims, forks: [], bindingConflicts: [] },
    ...opts,
  });

  function signedBatch(att, epoch, items, evidence = { forks: [], conflicts: [] }) {
    const batch = { v: 1, attester: att.nodeId, pubKey: att.kp.publicKey, epoch, items, evidence };
    batch.sig = signMessage(JSON.stringify({ ...batch, sig: undefined }), att.kp.secretKey);
    return batch;
  }

  test('buildBatch attaches verifiable canon assertions', async () => {
    const g = gossip([claim()], {
      canonicalNodeId: () => CANON_NODE, canonSign,
      canonPubkey: () => canonKp.publicKey,
    });
    const batch = await g.buildBatch(5);
    const canon = batch.items[0].canon;
    expect(canon).toBeTruthy();
    expect(canon.nodeId).toBe(CANON_NODE);
    expect(canon.claimRef).toBe(selfClaimRef(NODE, 5));
    expect(canon.value).toBe(claimLeafHash(claim()));
    expect(verifyAssertion(canon, canonKp.publicKey)).toBe(true);
  });

  test('bridge down → no canon field, batch still emitted', async () => {
    const g = gossip([claim()], {
      canonicalNodeId: () => CANON_NODE, canonSign: async () => null,
    });
    const batch = await g.buildBatch(5);
    expect(batch.items).toHaveLength(1);
    expect(batch.items[0].canon).toBeUndefined();
  });

  test('no canonSign → items carry no canon field', async () => {
    const batch = await gossip([claim()]).buildBatch(5);
    expect(batch.items[0].canon).toBeUndefined();
  });

  test('receive: bad canon signature drops the item', async () => {
    const e = NOW();
    const g = gossip([]);
    const it = {
      epoch: e, yakmeshNodeId: 'peer1', claimNodeId: NODE,
      seal: [0, 1, 2, 3],
      canon: {
        nodeId: CANON_NODE, epoch: e,
        claimRef: selfClaimRef(NODE, e), value: '11'.repeat(32),
        sig: 'aa'.repeat(3309), pubkey: canonKp.publicKey,
      },
    };
    const res = g.receive(signedBatch(A, e, [it]), null);
    expect(res.accepted).toBe(0);
    expect(g.stats.badSigs).toBe(1);
  });

  test('receive: canon claimRef binding enforced', async () => {
    const e = NOW();
    const g = gossip([]);
    // canon signs a DIFFERENT claimRef than the item's claim — reject
    const canon = await signAssertion({
      nodeId: CANON_NODE, epoch: e,
      claimRef: 'ff'.repeat(32), value: '11'.repeat(32),
    }, canonSign, canonKp.publicKey);
    const it = {
      epoch: e, yakmeshNodeId: 'peer1', claimNodeId: NODE,
      seal: [0, 1, 2, 3], canon,
    };
    const res = g.receive(signedBatch(A, e, [it]), null);
    expect(res.accepted).toBe(0);
    expect(g.stats.badSigs).toBe(1);
  });

  test('receive: same attester, conflicting canon values → equivocation', async () => {
    const e = NOW();
    const g = gossip([]);
    let ev = null;
    g.on('attesterEquivocation', (x) => { ev = x; });

    const mkCanon = (value) => signAssertion({
      nodeId: CANON_NODE, epoch: e,
      claimRef: selfClaimRef(NODE, e), value,
    }, canonSign, canonKp.publicKey);

    const itA = {
      epoch: e, yakmeshNodeId: 'peer1', claimNodeId: NODE,
      seal: [0, 1, 2, 3], canon: await mkCanon('11'.repeat(32)),
    };
    itA.leaf = '11'.repeat(32);
    const itB = {
      epoch: e, yakmeshNodeId: 'peer1', claimNodeId: NODE,
      seal: [0, 1, 2, 3], canon: await mkCanon('22'.repeat(32)),
    };
    itB.leaf = '22'.repeat(32);

    g.receive(signedBatch(A, e, [itA]), null);
    g.receive(signedBatch(A, e, [itB]), null);
    expect(ev).not.toBeNull();
    expect(ev.assertA.value).toBe('11'.repeat(32));
    expect(ev.assertB.value).toBe('22'.repeat(32));
    expect(ev.keystorePubkey).toBe(canonKp.publicKey);
  });

  test('receive: canon value must equal the item leaf', async () => {
    const e = NOW();
    const g = gossip([]);
    // canon asserts value ≠ item.leaf — the attester's signed word
    // doesn't match what it claimed to witness.
    const canon = await signAssertion({
      nodeId: CANON_NODE, epoch: e,
      claimRef: selfClaimRef(NODE, e), value: '99'.repeat(32),
    }, canonSign, canonKp.publicKey);
    const it = {
      epoch: e, yakmeshNodeId: 'peer1', claimNodeId: NODE,
      seal: [0, 1, 2, 3], leaf: '11'.repeat(32), canon,
    };
    const res = g.receive(signedBatch(A, e, [it]), null);
    expect(res.accepted).toBe(0);
  });
});
